style.css:
/* Header Styling */
header {
    background: #333333; /* Dark gray background for contrast */
    padding: 20px;
    text-align: center;
    border-bottom: 3px solid #FFFFFF; /* White border for separation */
}
header h1 {
    color: #FFFFFF; /* White text for better visibility */
    font-size: 2.5em;
    letter-spacing: 2px;
}

/* Table Styling */
table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
}
th, td {
    border: 2px solid #FFFFFF; /* Increase border thickness and use white color */
    padding: 10px; /* Add padding for better readability */
    text-align: left;
    color: #FFFFFF; /* Ensure all text in the table is white */
    font-weight: bold; /* Bold text for readability */
}
th {
    background: #FFFFFF; /* Dark gray background for headers */
}
tr:nth-child(odd) {
    background: #222222; /* Slightly lighter black for odd rows */
}
tr:nth-child(even) {
    background: #000000; /* Solid black for even rows */
}

/* First column link styling */
td:first-child a {
    color: #FFFFFF; /* Set link color to white */
    font-weight: bold; /* Make links bold */
    text-decoration: none; /* Remove underline */
}

/* Hover effect for links in the first column */
td:first-child a:hover {
    text-decoration: underline; /* Optional: underline on hover for clarity */
}
